  -- M13.L4 — Prochaines étapes
  INSERT INTO academy_lessons (module_id, course_id, title, sort_order, duration_minutes, content_blocks)
  VALUES (mid, cid, 'Prochaines étapes', 4, 10,
    $cb$[
      {"type":"section","label":"Mettre en pratique"},
      {"type":"step","number":1,"title":"Consolider la technique","content":"Réaliser les premières poses sur des modèles volontaires avant toute activité commerciale — et chronométrer pour ajuster les durées réelles. Tout exercice professionnel ou commercial reste soumis aux qualifications et règles applicables localement."},
      {"type":"step","number":2,"title":"Compléter les fiches","content":"Remplir la Fiche F8 (calculateur de tarif) et la Fiche F9 (menu de prestations) avec ses propres données avant d'ouvrir sa liste de clientes."},
      {"type":"step","number":3,"title":"Se renseigner sur son cadre légal","content":"Vérifier les obligations applicables (affichage des prix, données clients, qualifications requises) selon son statut et son pays d'exercice."},
      {"type":"step","number":4,"title":"Continuer à se former","content":"Suivre les évolutions des systèmes et des produits utilisés. Chaque nouveau fabricant ou système demande une lecture des instructions spécifiques."},
      {"type":"step","number":5,"title":"Observer et documenter","content":"Utiliser la fiche cliente à chaque prestation dès le départ. La traçabilité dès les premières clientes est plus facile à maintenir qu'à rattraper."},
      {"type":"step","number":6,"title":"Rejoindre la communauté Nahira","content":"Partager ses questions, ses avancées et ses cas pratiques avec les autres participantes — la progression en communauté est plus rapide et plus riche."},
      {"type":"tip","content":"La formation t'a donné les bases — la pratique te donnera le reste. Chaque ongle est une nouvelle situation, chaque cliente une nouvelle conversation. Ce qui distingue une bonne professionnelle, c'est moins la rapidité que la rigueur : observer avant d'agir, expliquer plutôt que présumer, et continuer à apprendre."},
      {"type":"je_maitrise","items":["Je peux décrire un signe unguéal sans en établir la cause","Je connais les 4 composantes de ma base tarifaire et je les ai calculées pour mes principales prestations","Je sais annoncer un refus ou une adaptation en 3 temps, calmement et sans s'excuser à l'excès","Ma fiche cliente est prête et ma Fiche F3 est adaptée à mon cadre d'exercice","Je sais à qui m'adresser (professionnel de santé, chambre professionnelle, expert-comptable) selon la situation rencontrée"]}
    ]$cb$
  );

